const std = @import("std");
const zml = @import("zml");

// Generated by zmlsmith from seed 800494.
test "reuse_buffer_sharding" {
    const platform = zml.testing.env();
    const allocator = std.testing.allocator;
    const io = std.testing.io;

    const Local = struct {
        fn forward(x0: zml.Tensor, x2: zml.Tensor) [1]zml.Tensor {
            const x1 = x0.bytes();
            _ = &x1;
            const x3 = x1.reuseBuffer(x2);
            _ = &x3;
            return .{x3};
        }
    };

    const mesh = try @constCast(platform).registerSharding("zmlsmith_800494", .mesh(.{ .data = .low_bandwidth, .model = .high_bandwidth }));
    const x0: zml.Tensor = .fromShape(zml.Shape.init(.{ .m = 1 }, .i32));
    const x2: zml.Tensor = .fromShape(zml.Shape.init(.{ .bytes = 4 }, .u8).withPartitioning(.{ .bytes = .data }));
    var exe = try zml.module.compile(allocator, io, Local.forward, .{ x0, x2 }, platform, .{ .shardings = &.{mesh} });
    defer exe.deinit();

    try zml.testing.expectEqualShapes(zml.Shape.init(.{ .bytes = 4 }, .u8), exe.output_shapes[0]);

    var b0: zml.Buffer = try .fromBytes(io, platform, x0.shape(), mesh, &[_]u8{
        0, 0, 0, 0,
    });
    defer b0.deinit();
    var b2: zml.Buffer = try .fromBytes(io, platform, x2.shape(), mesh, &[_]u8{
        0, 0, 0, 0,
    });
    defer b2.deinit();
    var res = try zml.testing.autoCall(allocator, io, &exe, Local.forward, .{ b0, b2 });
    defer for (&res) |*r| r.deinit();

    {
        const expected_data align(16) = [_]u8{
            0, 0, 0, 0,
        };
        const expected: zml.Slice = .init(zml.Shape.init(.{ .bytes = 4 }, .u8), @as([]const u8, &expected_data));
        const got = try res[0].toSliceAlloc(allocator, io);
        defer got.free(allocator);
        try std.testing.expectEqualSlices(u8, expected.constData(), got.constData());
    }
}
